\title{The Brualdi--Quinn--Massey Strong Chromatic Index Bound:\\
Tightness for Complete Bipartite Graphs and a Fibonacci--Riordan Bridge}
\author{Aristotle}
\date{2026-06-27}

\begin{document}
\maketitle

\begin{abstract}
The strong chromatic index $\chis(G)$ of a graph $G$ is the least number of
colors in a proper edge coloring whose color classes are induced matchings.
The Brualdi--Quinn--Massey (BQM) conjecture asserts that for every bipartite
graph $G$ with partite sets $A$ and $B$, $\chis(G) \le \DA \cdot \DB$, where
$\DA$ and $\DB$ are the maximum degrees on the two sides. The conjecture is
open; the best known general upper bound is $1.676\,\DA\DB$. We present a
self-contained development of the strong chromatic index through its
\emph{conflict graph}, establish a universal star-clique lower bound
$\chis(G) \ge \max(\DA,\DB)$, and prove that the complete bipartite graph
$K_{m,n}$ attains the BQM bound \textbf{with equality},
$\chis(K_{m,n}) = mn = \DA\DB$. This shows the product bound is best
possible. We then build a cross-domain bridge to number theory: writing
$A(n) = \sum_{k=0}^{n}\binom{n+k}{2k}$ for the steep-diagonal row sums of the
Pascal-like Riordan array $\binom{n+k}{2k}$, we prove $A(n) = \Fib{2n+1}$
(odd-indexed Fibonacci numbers) and deduce
$\chis(K_{A(a),A(b)}) = \Fib{2a+1}\cdot\Fib{2b+1}$. All results have been
formally verified.
\end{abstract}

\section{Introduction}

Edge colorings that respect proximity rather than mere adjacency arise wherever
a shared resource must avoid local interference: frequency assignment in dense
wireless networks, conflict-free time-slotting in distributed computation, and
channel allocation in sensor grids. The combinatorial abstraction is the
\emph{strong edge coloring}, in which two edges may share a color only if they
are at distance at least two. Its optimum, the \emph{strong chromatic index}
$\chis(G)$, measures the irreducible cost of interference-free assignment.

For bipartite graphs, Brualdi, Quinn, and Massey conjectured a clean ceiling:
the product of the two side-wise maximum degrees. The conjecture remains open,
with the best universal bound at $1.676\,\DA\DB$. This motivates two questions,
both answered here completely:
\begin{enumerate}
  \item Is the product bound of the correct order, and is it attained? We show
  the complete bipartite family attains it exactly.
  \item What is the arithmetic of the extreme? We show that for an explicit
  family of part sizes, the extremal value is a product of Fibonacci numbers.
\end{enumerate}

\paragraph{Contributions.}
\begin{itemize}
  \item A self-contained conflict-graph formalization of $\chis$
  (Section~\ref{sec:defs}).
  \item The universal lower bound $\chis(G) \ge \DA, \DB$ via a star clique
  (Theorem~\ref{thm:lower}, \texttt{maxDegA\_le\_strongChromaticIndex}).
  \item The tightness theorem $\chis(K_{m,n}) = \DA\DB = mn$
  (Theorem~\ref{thm:tight}, \texttt{completeBipartite\_strongChromaticIndex}),
  with \texttt{completeBipartite\_satisfies\_BQM}.
  \item The Fibonacci row-sum identity $\sum_{k=0}^{n}\binom{n+k}{2k}=\Fib{2n+1}$
  (Theorem~\ref{thm:fib}, \texttt{pascalRiordanA\_eq\_fib}) and companion
  \texttt{pascalRiordanB\_eq\_fib}, with \texttt{pascalRiordan\_three\_term}.
  \item The bridge theorem $\chis(K_{A(a),A(b)}) = \Fib{2a+1}\Fib{2b+1}$
  (Theorem~\ref{thm:bridge},
  \texttt{strongChromaticIndex\_riordan\_complete\_bipartite}).
\end{itemize}

\section{Definitions}\label{sec:defs}

Throughout, $G$ is a finite \emph{bipartite graph} with disjoint partite sets
$A$ and $B$; every edge joins a vertex of $A$ to a vertex of $B$, written
$(a,b)$.

\begin{definition}[Degrees]
For $a \in A$, $\deg(a)$ is the number of $b \in B$ adjacent to $a$, and
$\DA = \max_{a\in A}\deg(a)$; $\DB$ is symmetric. For an empty side the maximum
is taken to be $0$; degree statements assume the relevant side is nonempty.
\end{definition}

\begin{definition}[Strong edge coloring]
A coloring of $E(G)$ is \emph{strong} if every color class is an induced
matching: two edges of the same color are non-adjacent and no edge of $G$ joins
an endpoint of one to an endpoint of the other (distance $\ge 2$).
\end{definition}

\begin{definition}[Conflict graph]
The \emph{conflict graph} $C(G)$ has vertex set $E(G)$; distinct edges
$e,f$ are adjacent in $C(G)$ iff they cannot share a color, i.e. they are at
distance $\le 1$ in $G$ (\texttt{conflictGraph}).
\end{definition}

\begin{definition}[Strong chromatic index]
$\chis(G) = \chi\big(C(G)\big)$ (\texttt{strongChromaticIndex}), valued in
$\mathbb{N}^\infty$ and finite for finite $G$.
\end{definition}

\begin{definition}[Complete bipartite graph]
$K_{m,n}$ has $|A|=m$, $|B|=n$, and every $a\in A$ adjacent to every $b\in B$
(\texttt{completeAdj}). It has $mn$ edges; each $A$-vertex has degree $n$ and
each $B$-vertex has degree $m$.
\end{definition}

\begin{definition}[Riordan row sums]
For the Pascal-like Riordan array $t_{n,k}=\binom{n+k}{2k}$ (OEIS A085478),
$$A(n) = \sum_{k=0}^{n}\binom{n+k}{2k}, \qquad
  B(n) = \sum_{k=0}^{n}\binom{n+k}{2k+1}$$
(\texttt{pascalRiordanA}, \texttt{pascalRiordanB}).
\end{definition}

\section{The bound is tight: complete bipartite graphs}

\begin{theorem}[Star-clique lower bound; \texttt{maxDegA\_le\_strongChromaticIndex}]\label{thm:lower}
For every bipartite $G$ with $A\ne\varnothing$, $\chis(G)\ge\DA$, and
symmetrically $\chis(G)\ge\DB$. Hence $\chis(G)\ge\max(\DA,\DB)$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $a^\star$ attain $\DA$ and let $S$ be its $\DA$ incident edges. Any two
edges in $S$ share $a^\star$, hence are adjacent in $C(G)$; so $S$ is a clique
of size $\DA$. Since the chromatic number dominates the clique number,
$\chis(G)=\chi(C(G))\ge|S|=\DA$.
\end{proof}

\begin{lemma}[Conflict graph of $K_{m,n}$ is complete]\label{lem:complete}
$C(K_{m,n})$ is the complete graph on its $mn$ edges.
\end{lemma}

\begin{proof}[Proof sketch]
Take distinct edges $e=(a_1,b_1)$, $f=(a_2,b_2)$. If $a_1=a_2$ or $b_1=b_2$
they are adjacent. Otherwise $(a_1,b_2)$ is an edge of $K_{m,n}$ joining an
endpoint of $e$ to an endpoint of $f$, putting them at distance $1$. Either way
they conflict, so $C(K_{m,n})=\top$.
\end{proof}

\begin{theorem}[Tightness; \texttt{completeBipartite\_strongChromaticIndex}]\label{thm:tight}
For $K_{m,n}$ with nonempty sides, $\chis(K_{m,n}) = \DA\cdot\DB = m\cdot n$.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:complete}, $C(K_{m,n})=\top$ on $mn$ vertices, so
$\chis(K_{m,n})=mn$ (chromatic number of a complete graph). The degree
formulas \texttt{maxDegA\_complete}, \texttt{maxDegB\_complete} give $\DA=n$,
$\DB=m$, hence $\DA\DB=mn$.
\end{proof}

\begin{corollary}[BQM holds and is sharp; \texttt{completeBipartite\_satisfies\_BQM}]
The complete bipartite family satisfies $\chis\le\DA\DB$ with equality.
No universal statement $\chis(G)\le c\,\DA\DB$ with $c<1$ can hold.
\end{corollary}

\begin{remark}
The general upper bound $\chis(G)\le\DA\DB$ is the open BQM conjecture,
recorded as a named statement \texttt{BQMConjecture} and \emph{not} claimed as
a theorem. Together with $\chis(G)\le 1.676\,\DA\DB$, our results localize the
truth to $[\max(\DA,\DB),\,1.676\,\DA\DB]$, with $\DA\DB$ the conjectured and
provably attained ceiling.
\end{remark}

\section{The Fibonacci row-sum identity}

\begin{lemma}[Coupled Pascal recurrences]\label{lem:pascal}
$B(n+1)=A(n)+B(n)$ and $A(n+1)=A(n)+B(n+1)$.
\end{lemma}

\begin{proof}[Proof sketch]
For $B$ (\texttt{pascalRiordanB\_succ}), apply Pascal's rule
$\binom{(n+1)+k}{2k+1}=\binom{n+k}{2k}+\binom{n+k}{2k+1}$ termwise and sum. For
$A$ (\texttt{pascalRiordanA\_succ}), a reindexing $k\mapsto k+1$ avoids
truncated natural-number subtraction; the odd lower index $2k+1$ removes all
subtraction hazards.
\end{proof}

\begin{theorem}[Row-sum Fibonacci identity; \texttt{pascalRiordanA\_eq\_fib}, \texttt{pascalRiordanB\_eq\_fib}]\label{thm:fib}
With $\Fib{0}=0,\Fib{1}=1$,
$$A(n)=\sum_{k=0}^{n}\binom{n+k}{2k}=\Fib{2n+1}, \qquad
  B(n)=\sum_{k=0}^{n}\binom{n+k}{2k+1}=\Fib{2n}.$$
\end{theorem}

\begin{proof}[Proof sketch]
Simultaneous induction (\texttt{pascalRiordan\_pair}). Base:
$A(0)=1=\Fib{1}$, $B(0)=0=\Fib{0}$. Step: by Lemma~\ref{lem:pascal},
$B(n+1)=\Fib{2n+1}+\Fib{2n}=\Fib{2n+2}$ and
$A(n+1)=\Fib{2n+1}+\Fib{2n+2}=\Fib{2n+3}$.
\end{proof}

\begin{theorem}[Three-term recurrence; \texttt{pascalRiordan\_three\_term}]
$A(n+2)=3A(n+1)-A(n)$, the shadow of the generating function
$(1-x)/(1-3x+x^2)$.
\end{theorem}

\begin{proof}[Proof sketch]
Substitute $A(n)=\Fib{2n+1}$ and apply $\Fib{2n+5}=3\Fib{2n+3}-\Fib{2n+1}$.
\end{proof}

First values: $A(0..5)=1,2,5,13,34,89=\Fib{1},\Fib{3},\Fib{5},\Fib{7},\Fib{9},\Fib{11}$
and $B(0..5)=0,1,3,8,21,55=\Fib{0},\Fib{2},\Fib{4},\Fib{6},\Fib{8},\Fib{10}$.

\section{The bridge: strong chromatic index meets Fibonacci}

\begin{lemma}[Positivity; \texttt{pascalRiordanA\_pos}]\label{lem:pos}
$A(n)>0$ for all $n$ (the $k=0$ term is $1$; equivalently $\Fib{2n+1}\ge1$),
so $\mathrm{Fin}(A(a))$ and $\mathrm{Fin}(A(b))$ are nonempty, supplying the
\texttt{Nonempty}/\texttt{NeZero} instances the degree formula requires.
\end{lemma}

\begin{theorem}[Bridge theorem; \texttt{strongChromaticIndex\_riordan\_complete\_bipartite}]\label{thm:bridge}
For all $a,b\in\mathbb{N}$,
$$\chis\big(K_{A(a),A(b)}\big) = \Fib{2a+1}\cdot\Fib{2b+1}.$$
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:pos} both parts are nonempty, so Theorem~\ref{thm:tight} gives
$\chis(K_{A(a),A(b)})=A(a)\cdot A(b)$. Substitute $A(a)=\Fib{2a+1}$,
$A(b)=\Fib{2b+1}$ from Theorem~\ref{thm:fib}.
\end{proof}

\begin{theorem}[Binomial form; \texttt{strongChromaticIndex\_riordan\_binomial}]
$$\chis\big(K_{A(a),A(b)}\big) =
  \Big(\textstyle\sum_{k=0}^{a}\binom{a+k}{2k}\Big)
  \Big(\textstyle\sum_{k=0}^{b}\binom{b+k}{2k}\Big).$$
\end{theorem}

\begin{proof}[Proof sketch]
Immediate from Theorem~\ref{thm:bridge} and Theorem~\ref{thm:fib}.
\end{proof}

\paragraph{Why the bridge is genuine.} The left side is a graph-coloring
invariant requiring the conflict-graph analysis; the right side requires the
binomial-to-Fibonacci collapse. Multiplicativity of $\chis$ on complete
bipartite graphs is the lever: any factorization identity for a sequence lifts
to an identity for $\chis$.

\paragraph{Golden-ratio growth.} Since $\Fib{m}\sim\varphi^m/\sqrt5$ with
$\varphi=(1+\sqrt5)/2$, $\chis(K_{A(a),A(b)})\sim\varphi^{2a+2b+2}/5$, so each
unit increment of $a$ or $b$ multiplies the index asymptotically by
$\varphi^2\approx2.618$.

\section{Applications}
\begin{itemize}
  \item \textbf{Wireless and sensor networks.} $\chis$ is the minimum number of
  frequency/time slots for interference-free communication at range two; the
  tightness result gives the exact spectrum requirement for fully-connected
  bipartite topologies, and the lower bound a universal floor.
  \item \textbf{Conflict-free scheduling.} $\chis$ counts minimum scheduling
  rounds when assignments within one hop interfere.
  \item \textbf{Combinatorial identities.} The bridge maps a graph invariant
  onto the Fibonacci sequence A001519 via the Riordan array A085478.
\end{itemize}

\section{Discussion}
The product bound $\DA\DB$ is the correct ceiling: attained with equality by
complete bipartite graphs, with a matching universal floor $\max(\DA,\DB)$. The
conflict-graph formulation reduces a distance-constrained coloring to a standard
chromatic-number computation, making both the clique lower bound and the
complete-graph equality immediate. The Fibonacci bridge shows the extremal
values are products of odd-indexed Fibonacci numbers growing at $\varphi^2$.

\section{Future Directions}
\paragraph{C1. Sandwich conjecture.}
$\max(\DA,\DB)\le\chis(G)\le\DA\DB$ for all bipartite $G$: lower side proved,
upper side open. We conjecture both ends are simultaneously attainable.

\paragraph{C2. Equality classification.}
$\chis(G)=\DA\DB$ iff $G$ is complete bipartite; equality forces $C(G)=\top$.

\paragraph{C3. Fibonacci ladder.}
For $K_{A(a),B(b)}$ with $B(n)=\Fib{2n}$, conjecture
$\chis(K_{A(a),B(b)})=\Fib{2a+1}\Fib{2b}$, and that every product $\Fib{i}\Fib{j}$
arises as a strong chromatic index.

\paragraph{C4. Conflict-degree greedy bound.}
$\chis(G)\le 2\DA\DB+\DA+\DB-1$ via bounding the conflict-graph degree and
applying $\chi\le\Delta_{\text{conflict}}+1$.

\section{Conclusion}
We gave a self-contained account of the strong chromatic index via its conflict
graph, proved a universal lower bound and the exact value
$\chis(K_{m,n})=\DA\DB$, and constructed a verified bridge identifying the
extremal invariant on Riordan-sized complete bipartite graphs with
$\Fib{2a+1}\Fib{2b+1}$. The BQM conjecture remains open in general, but its
bound is now known to be sharp, with the extreme carrying the signature of the
golden ratio.

