    E <- { (a,b) : 0 <= a < m, 0 <= b < n }
    if E empty: return 0
    for each unordered pair {e, f} in E:
        if distance_in_G(e, f) <= 1:           # always true for K_{m,n}
            mark e and f adjacent in conflict graph C
    color <- empty map
    for v in E:                                 # greedy coloring
        used <- { color[u] : u adjacent to v, u colored }
        color[v] <- smallest nonnegative integer not in used
    return 1 + max(color.values())

